import{_ as t,o as a,c as i,a2 as s}from"./chunks/framework.CHeM0PsO.js";const h=JSON.parse('{"title":"Explorateur TUI","description":"","frontmatter":{},"headers":[],"relativePath":"fr/advanced/tui.md","filePath":"fr/advanced/tui.md","lastUpdated":1784903584000}'),r={name:"fr/advanced/tui.md"};function o(d,e,n,l,c,u){return a(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="explorateur-tui" tabindex="-1">Explorateur TUI <a class="header-anchor" href="#explorateur-tui" aria-label="Permalink to &quot;Explorateur TUI&quot;">​</a></h1><h2 id="apercu" tabindex="-1">Aperçu <a class="header-anchor" href="#apercu" aria-label="Permalink to &quot;Aperçu&quot;">​</a></h2><p>swag2mcp inclut une TUI (Interface Utilisateur Terminal) intégrée pour l&#39;exploration interactive d&#39;API. C&#39;est une application terminal plein écran qui vous permet de rechercher, parcourir, inspecter et invoquer des points d&#39;accès API sans quitter le terminal.</p><h2 id="lancement" tabindex="-1">Lancement <a class="header-anchor" href="#lancement" aria-label="Permalink to &quot;Lancement&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span></span></code></pre></div><p>Si aucun fichier de configuration n&#39;existe, la TUI démarrera automatiquement l&#39;assistant d&#39;initialisation d&#39;abord.</p><h2 id="modes" tabindex="-1">Modes <a class="header-anchor" href="#modes" aria-label="Permalink to &quot;Modes&quot;">​</a></h2><p>La TUI a trois modes, accessibles avec la touche <code>Tab</code> :</p><h3 id="mode-recherche" tabindex="-1">Mode Recherche <a class="header-anchor" href="#mode-recherche" aria-label="Permalink to &quot;Mode Recherche&quot;">​</a></h3><p>Recherche en texte intégral dans tous les points d&#39;accès de toutes les specs. Prend en charge la même syntaxe de requête que l&#39;outil MCP <code>search</code>.</p><ul><li>Saisissez une requête pour rechercher les noms, chemins et descriptions des points d&#39;accès</li><li>Filtrez les résultats par méthode, étiquette ou chemin</li><li>Affichez les détails d&#39;un point d&#39;accès avec une seule touche</li><li>Naviguez dans les résultats avec la pagination (10 éléments par page)</li></ul><h3 id="mode-parcourir" tabindex="-1">Mode Parcourir <a class="header-anchor" href="#mode-parcourir" aria-label="Permalink to &quot;Mode Parcourir&quot;">​</a></h3><p>Navigation arborescente dans la hiérarchie des specs :</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Spec → Collection → Tag → Point d&#39;accès</span></span></code></pre></div><ul><li>Descendez dans l&#39;arborescence pour trouver des points d&#39;accès spécifiques</li><li>Affichez les détails d&#39;un point d&#39;accès (paramètres, corps de requête, réponses)</li><li>Invoquez l&#39;API directement depuis la TUI</li><li>Sauvegardez les détails d&#39;un point d&#39;accès sous forme de fichier JSON</li></ul><h3 id="mode-auth" tabindex="-1">Mode Auth <a class="header-anchor" href="#mode-auth" aria-label="Permalink to &quot;Mode Auth&quot;">​</a></h3><p>Affichez les jetons d&#39;authentification et les en-têtes pour n&#39;importe quelle spec. Utile pour le débogage ou la génération de commandes curl.</p><h2 id="controles" tabindex="-1">Contrôles <a class="header-anchor" href="#controles" aria-label="Permalink to &quot;Contrôles&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Touche</th><th>Action</th></tr></thead><tbody><tr><td><code>↑</code> / <code>↓</code></td><td>Naviguer vers le haut/bas</td></tr><tr><td><code>Entrée</code></td><td>Sélectionner ou ouvrir</td></tr><tr><td><code>Échap</code></td><td>Revenir d&#39;un niveau</td></tr><tr><td><code>Tab</code></td><td>Basculer entre les modes Recherche, Parcourir et Auth</td></tr><tr><td><code>/</code></td><td>Activer la saisie de recherche</td></tr><tr><td><code>N</code> / <code>P</code></td><td>Page suivante / précédente</td></tr><tr><td><code>B</code></td><td>Retour à l&#39;écran précédent</td></tr><tr><td><code>M</code></td><td>Retour au menu principal</td></tr><tr><td><code>S</code></td><td>Sauvegarder les détails du point d&#39;accès en JSON</td></tr><tr><td><code>q</code> / <code>Ctrl+C</code></td><td>Quitter</td></tr></tbody></table><h2 id="etats" tabindex="-1">États <a class="header-anchor" href="#etats" aria-label="Permalink to &quot;États&quot;">​</a></h2><p>La TUI passe par ces états au fur et à mesure de votre navigation :</p><ol><li><strong>Chargement</strong> — chargement des données depuis l&#39;espace de travail</li><li><strong>Recherche</strong> — mode recherche avec saisie de requête</li><li><strong>Parcourir</strong> — mode parcourir avec liste des specs</li><li><strong>Liste des specs</strong> — liste de toutes les specs</li><li><strong>Liste des collections</strong> — collections dans une spec</li><li><strong>Liste des étiquettes</strong> — étiquettes dans une collection</li><li><strong>Liste des points d&#39;accès</strong> — points d&#39;accès dans une étiquette</li><li><strong>Détail du point d&#39;accès</strong> — informations complètes sur le point d&#39;accès</li><li><strong>Résultat d&#39;invocation</strong> — résultat de l&#39;appel API</li><li><strong>Erreur</strong> — état d&#39;erreur avec message</li></ol><h2 id="vue-detaillee-du-point-d-acces" tabindex="-1">Vue détaillée du point d&#39;accès <a class="header-anchor" href="#vue-detaillee-du-point-d-acces" aria-label="Permalink to &quot;Vue détaillée du point d&#39;accès&quot;">​</a></h2><p>Lorsque vous sélectionnez un point d&#39;accès, la TUI affiche :</p><ul><li>Méthode HTTP et chemin</li><li>URL de base et URL complète</li><li>Résumé et description</li><li>Tous les paramètres (nom, emplacement, type, requis)</li><li>Schéma du corps de la requête (le cas échéant)</li><li>Codes de réponse et schémas</li><li>Statut de dépréciation</li></ul><h2 id="prerequis" tabindex="-1">Prérequis <a class="header-anchor" href="#prerequis" aria-label="Permalink to &quot;Prérequis&quot;">​</a></h2><ul><li><strong>Taille du terminal :</strong> Au moins 80×24 caractères</li><li><strong>Émulateur de terminal :</strong> Fonctionne dans la plupart des terminaux modernes (iTerm2, Terminal.app, GNOME Terminal, Windows Terminal, etc.)</li><li><strong>SSH :</strong> Fonctionne via des connexions SSH</li></ul><h2 id="notes-importantes" tabindex="-1">Notes importantes <a class="header-anchor" href="#notes-importantes" aria-label="Permalink to &quot;Notes importantes&quot;">​</a></h2><ul><li><strong>Auto-initialisation</strong> — si aucun fichier de configuration n&#39;existe, la TUI démarre automatiquement l&#39;assistant d&#39;initialisation</li><li><strong>Pagination</strong> — les listes sont paginées à 10 éléments par page. Utilisez <code>N</code> et <code>P</code> pour naviguer</li><li><strong>Sauvegarde des détails du point d&#39;accès</strong> — appuyez sur <code>S</code> dans la vue détaillée du point d&#39;accès pour sauvegarder les détails complets sous forme de fichier JSON dans le répertoire courant</li><li><strong>Mode Auth</strong> — affiche les jetons et en-têtes pour le débogage. En production, l&#39;outil auth peut être désactivé avec <code>--disable-llm-auth</code></li></ul>',29)])])}const m=t(r,[["render",o]]);export{h as __pageData,m as default};
